enum RdRules {
    static let all: [RdRule] = [
        RdRule(place: "Queensland, Australia", check: "Blue card, the Queensland Working with Children Check", law: "yes", issuer: "Blue Card Services, Queensland Government", cost: "$108.30 for paid work or business, from 1 July 2026", validity: "3 years, unless suspended or cancelled", steps: ["Get a Customer Reference Number and photo from Transport and Main Roads.","Register for a Blue Card Services online account.","Apply in the online portal or send a paper form.","Pay the paid applicant fee."], visa: "Working Holiday visa, subclass 417, or Work and Holiday visa, subclass 462. Family sponsorship is not required.", age: "Subclass 417: age 18 to 30, or 18 to 35 for Canada, Cyprus, Denmark, Finland, France, Germany, Ireland, Italy, Republic of Korea, and the United Kingdom. Subclass 462: age 18 to 30.", countries: "Subclass 417: Belgium, Canada, Cyprus, Denmark, Estonia, Finland, France, Germany, Hong Kong, Ireland, Italy, Japan, Republic of Korea, Malta, Netherlands, Norway, Sweden, Taiwan, and the United Kingdom. Subclass 462: Argentina, Austria, Brazil, Chile, China, Czech Republic, Ecuador, Greece, Hungary, India, Indonesia, Israel, Luxembourg, Malaysia, Mongolia, Papua New Guinea, Peru, Poland, Portugal, San Marino, Singapore, Slovak Republic, Slovenia, Spain, Switzerland, Thailand, Türkiye, Uruguay, United States, and Vietnam.", stay: "Up to 12 months per visa.", hours: "Not confirmed", source: "https://www.qld.gov.au/jobs/blue-card/required/individuals-businesses/childcare-services"),
        RdRule(place: "New South Wales, Australia", check: "Working with Children Check, or WWCC. Nannies and au pairs are in scope. Private home babysitters are exempt.", law: "Not confirmed", issuer: "Office of the Children's Guardian, New South Wales Government", cost: "$112 for paid workers", validity: "5 years, with ongoing monitoring", steps: ["Apply online through Service NSW.","Fill in the form using your name as it appears on your identity papers.","Show four original identity papers at a Service NSW Centre.","Pay the fee for paid work."], visa: "Working Holiday visa, subclass 417, or Work and Holiday visa, subclass 462. Family sponsorship is not required.", age: "Subclass 417: age 18 to 30, or 18 to 35 for Canada, Cyprus, Denmark, Finland, France, Germany, Ireland, Italy, Republic of Korea, and the United Kingdom. Subclass 462: age 18 to 30.", countries: "Subclass 417: Belgium, Canada, Cyprus, Denmark, Estonia, Finland, France, Germany, Hong Kong, Ireland, Italy, Japan, Republic of Korea, Malta, Netherlands, Norway, Sweden, Taiwan, and the United Kingdom. Subclass 462: Argentina, Austria, Brazil, Chile, China, Czech Republic, Ecuador, Greece, Hungary, India, Indonesia, Israel, Luxembourg, Malaysia, Mongolia, Papua New Guinea, Peru, Poland, Portugal, San Marino, Singapore, Slovak Republic, Slovenia, Spain, Switzerland, Thailand, Türkiye, Uruguay, United States, and Vietnam.", stay: "Up to 12 months per visa.", hours: "Not confirmed", source: "https://ocg.nsw.gov.au/parents-and-carers/what-parents-need-know-about-working-children-check"),
        RdRule(place: "Victoria, Australia", check: "Working with Children Check, or WWC Check.", law: "Not confirmed", issuer: "Social Services Regulator, Victorian Government", cost: "$139.20 for an employee clearance, from 1 July 2026 to 30 June 2027", validity: "5 years, unless suspended, cancelled, or surrendered", steps: ["Complete the required online child safety training.","Apply online through Service Victoria.","Prove your identity, fill in the form, and pay the fee."], visa: "Working Holiday visa, subclass 417, or Work and Holiday visa, subclass 462. Family sponsorship is not required.", age: "Subclass 417: age 18 to 30, or 18 to 35 for Canada, Cyprus, Denmark, Finland, France, Germany, Ireland, Italy, Republic of Korea, and the United Kingdom. Subclass 462: age 18 to 30.", countries: "Subclass 417: Belgium, Canada, Cyprus, Denmark, Estonia, Finland, France, Germany, Hong Kong, Ireland, Italy, Japan, Republic of Korea, Malta, Netherlands, Norway, Sweden, Taiwan, and the United Kingdom. Subclass 462: Argentina, Austria, Brazil, Chile, China, Czech Republic, Ecuador, Greece, Hungary, India, Indonesia, Israel, Luxembourg, Malaysia, Mongolia, Papua New Guinea, Peru, Poland, Portugal, San Marino, Singapore, Slovak Republic, Slovenia, Spain, Switzerland, Thailand, Türkiye, Uruguay, United States, and Vietnam.", stay: "Up to 12 months per visa.", hours: "Not confirmed", source: "https://www.vic.gov.au/WWC-Check-explained"),
        RdRule(place: "South Australia", check: "Working with Children Check. Directly hired nannies and au pairs need it. Privately arranged babysitters do not.", law: "Yes", issuer: "Department of Human Services Screening Unit, called Screening SA", cost: "$145 for paid employees. Free for volunteers.", validity: "5 years", steps: ["Create or log in to a personal Screening SA account.","Apply for a Working with Children Check and verify your identity.","Pay $145 online and submit the application."], visa: "There is no au pair specific visa. Eligible applicants can use the Working Holiday visa subclass 417 or Work and Holiday visa subclass 462. The applicant applies alone. The family does not sponsor these visas.", age: "Subclass 417: ages 18 to 30 for Belgium, Estonia, Hong Kong, Japan, Malta, Netherlands, Norway, Sweden and Taiwan. Ages 18 to 35 for Canada, Cyprus, Denmark, Finland, France, Germany, Ireland, Italy, Republic of Korea and the United Kingdom. Subclass 462: ages 18 to 30 for all eligible passports.", countries: "Subclass 417 passports: Belgium, Canada, Cyprus, Denmark, Estonia, Finland, France, Germany, Hong Kong, Ireland, Italy, Japan, Republic of Korea, Malta, Netherlands, Norway, Sweden, Taiwan and the United Kingdom. Taiwan passports must not be official or diplomatic. United Kingdom includes British National Overseas passports. Subclass 462 passports: Argentina, Austria, Brazil, Chile, China, Czech Republic, Ecuador, Greece, Hungary, India, Indonesia, Israel, Luxembourg, Malaysia, Mongolia, Papua New Guinea, Peru, Poland, Portugal, San Marino, Singapore, Slovak Republic, Slovenia, Spain, Switzerland, Thailand, Türkiye, Uruguay, United States and Vietnam.", stay: "Up to 12 months for a first visa.", hours: "No weekly hour cap is stated in the official visa rules.", source: "https://www.sa.gov.au/topics/rights-and-law/rights-and-responsibilities/screening-checks/screening-wwcc/for-parents"),
        RdRule(place: "Western Australia", check: "Working with Children Check card. Formal paid nanny or child minding work needs a card. Informal babysitting favors do not.", law: "Yes", issuer: "Working with Children Screening Unit, Department of Communities", cost: "$87 for paid employees and self employed workers. GST is not included.", validity: "3 years", steps: ["Get a paid worker form from an authorised Australia Post outlet or the Screening Unit.","Complete the form with the employer or organisation details.","Lodge the form with identity documents and the fee at Australia Post."], visa: "There is no au pair specific visa. Eligible applicants can use the Working Holiday visa subclass 417 or Work and Holiday visa subclass 462. The applicant applies alone. The family does not sponsor these visas.", age: "Subclass 417: ages 18 to 30 for Belgium, Estonia, Hong Kong, Japan, Malta, Netherlands, Norway, Sweden and Taiwan. Ages 18 to 35 for Canada, Cyprus, Denmark, Finland, France, Germany, Ireland, Italy, Republic of Korea and the United Kingdom. Subclass 462: ages 18 to 30 for all eligible passports.", countries: "Subclass 417 passports: Belgium, Canada, Cyprus, Denmark, Estonia, Finland, France, Germany, Hong Kong, Ireland, Italy, Japan, Republic of Korea, Malta, Netherlands, Norway, Sweden, Taiwan and the United Kingdom. Taiwan passports must not be official or diplomatic. United Kingdom includes British National Overseas passports. Subclass 462 passports: Argentina, Austria, Brazil, Chile, China, Czech Republic, Ecuador, Greece, Hungary, India, Indonesia, Israel, Luxembourg, Malaysia, Mongolia, Papua New Guinea, Peru, Poland, Portugal, San Marino, Singapore, Slovak Republic, Slovenia, Spain, Switzerland, Thailand, Türkiye, Uruguay, United States and Vietnam.", stay: "Up to 12 months for a first visa.", hours: "No weekly hour cap is stated in the official visa rules.", source: "https://www.wa.gov.au/organisation/department-of-communities/parents-and-guardians-information-page"),
        RdRule(place: "Tasmania", check: "Registration to Work with Vulnerable People card. Nannies and au pairs are listed. Babysitting through a private arrangement is exempt.", law: "Yes", issuer: "Tasmanian Department of Justice, Registration to Work with Vulnerable People", cost: "$137.20 for paid work. Volunteer only registration is free during the fee relief period that began 1 January 2026.", validity: "5 years", steps: ["Complete the online form and choose Employment or Volunteer for paid work.","Pay $137.20 online or at Service Tasmania.","Visit Service Tasmania within 21 days with the same identity documents and have your photo taken."], visa: "There is no au pair specific visa. Eligible applicants can use the Working Holiday visa subclass 417 or Work and Holiday visa subclass 462. The applicant applies alone. The family does not sponsor these visas.", age: "Subclass 417: ages 18 to 30 for Belgium, Estonia, Hong Kong, Japan, Malta, Netherlands, Norway, Sweden and Taiwan. Ages 18 to 35 for Canada, Cyprus, Denmark, Finland, France, Germany, Ireland, Italy, Republic of Korea and the United Kingdom. Subclass 462: ages 18 to 30 for all eligible passports.", countries: "Subclass 417 passports: Belgium, Canada, Cyprus, Denmark, Estonia, Finland, France, Germany, Hong Kong, Ireland, Italy, Japan, Republic of Korea, Malta, Netherlands, Norway, Sweden, Taiwan and the United Kingdom. Taiwan passports must not be official or diplomatic. United Kingdom includes British National Overseas passports. Subclass 462 passports: Argentina, Austria, Brazil, Chile, China, Czech Republic, Ecuador, Greece, Hungary, India, Indonesia, Israel, Luxembourg, Malaysia, Mongolia, Papua New Guinea, Peru, Poland, Portugal, San Marino, Singapore, Slovak Republic, Slovenia, Spain, Switzerland, Thailand, Türkiye, Uruguay, United States and Vietnam.", stay: "Up to 12 months for a first visa.", hours: "No weekly hour cap is stated in the official visa rules.", source: "https://www.justice.tas.gov.au/rwvp/apply/do-you-need-a-rwvp/registration-decision-tool/decision-tool"),
        RdRule(place: "Northern Territory", check: "Working with Children Clearance, also called an Ochre Card. Family and friend babysitting agreements do not need one.", law: "Yes", issuer: "Northern Territory Screening Authority, working with SAFE NT in NT Police", cost: "$89 for paid work. $8 for volunteers.", validity: "2 years", steps: ["Apply online or fill in the paid work application form.","Provide at least 100 points of identity documents and a photo.","Pay $89 and submit online, in person or by mail to SAFE NT or an approved service point."], visa: "There is no au pair specific visa. Eligible applicants can use the Working Holiday visa subclass 417 or Work and Holiday visa subclass 462. The applicant applies alone. The family does not sponsor these visas.", age: "Subclass 417: ages 18 to 30 for Belgium, Estonia, Hong Kong, Japan, Malta, Netherlands, Norway, Sweden and Taiwan. Ages 18 to 35 for Canada, Cyprus, Denmark, Finland, France, Germany, Ireland, Italy, Republic of Korea and the United Kingdom. Subclass 462: ages 18 to 30 for all eligible passports.", countries: "Subclass 417 passports: Belgium, Canada, Cyprus, Denmark, Estonia, Finland, France, Germany, Hong Kong, Ireland, Italy, Japan, Republic of Korea, Malta, Netherlands, Norway, Sweden, Taiwan and the United Kingdom. Taiwan passports must not be official or diplomatic. United Kingdom includes British National Overseas passports. Subclass 462 passports: Argentina, Austria, Brazil, Chile, China, Czech Republic, Ecuador, Greece, Hungary, India, Indonesia, Israel, Luxembourg, Malaysia, Mongolia, Papua New Guinea, Peru, Poland, Portugal, San Marino, Singapore, Slovak Republic, Slovenia, Spain, Switzerland, Thailand, Türkiye, Uruguay, United States and Vietnam.", stay: "Up to 12 months for a first visa.", hours: "No weekly hour cap is stated in the official visa rules.", source: "https://nt.gov.au/emergency/child-safety/working-with-children-clearance/wwcc-before-you-apply"),
        RdRule(place: "Australian Capital Territory", check: "Working with Vulnerable People registration. Commercial nanny and babysitting services are covered. Direct family hires are not confirmed.", law: "Not confirmed", issuer: "Access Canberra, ACT Government", cost: "$163 for paid work. Free for volunteer only registration.", validity: "5 years", steps: ["Create an ACT Government Digital Account and start the WWVP application.","Submit the application and pay $163.","Verify identity with four documents at Access Canberra or by post. The card is mailed if approved."], visa: "There is no au pair specific visa. Eligible applicants can use the Working Holiday visa subclass 417 or Work and Holiday visa subclass 462. The applicant applies alone. The family does not sponsor these visas.", age: "Subclass 417: ages 18 to 30 for Belgium, Estonia, Hong Kong, Japan, Malta, Netherlands, Norway, Sweden and Taiwan. Ages 18 to 35 for Canada, Cyprus, Denmark, Finland, France, Germany, Ireland, Italy, Republic of Korea and the United Kingdom. Subclass 462: ages 18 to 30 for all eligible passports.", countries: "Subclass 417 passports: Belgium, Canada, Cyprus, Denmark, Estonia, Finland, France, Germany, Hong Kong, Ireland, Italy, Japan, Republic of Korea, Malta, Netherlands, Norway, Sweden, Taiwan and the United Kingdom. Taiwan passports must not be official or diplomatic. United Kingdom includes British National Overseas passports. Subclass 462 passports: Argentina, Austria, Brazil, Chile, China, Czech Republic, Ecuador, Greece, Hungary, India, Indonesia, Israel, Luxembourg, Malaysia, Mongolia, Papua New Guinea, Peru, Poland, Portugal, San Marino, Singapore, Slovak Republic, Slovenia, Spain, Switzerland, Thailand, Türkiye, Uruguay, United States and Vietnam.", stay: "Up to 12 months for a first visa.", hours: "No weekly hour cap is stated in the official visa rules.", source: "https://www.accesscanberra.act.gov.au/business-and-work/working-with-vulnerable-people/working-with-vulnerable-people-scheme"),
        RdRule(place: "New Zealand", check: "Children's Act safety check, including a police vet, for covered service work. Private family nannies and babysitters are exempt.", law: "No", issuer: "The employer or contracting organisation arranges the safety check. New Zealand Police provides the police vet.", cost: "Not confirmed", validity: "3 years when required for covered workers. It is not required for private family hires.", steps: ["Check if the job is with a covered, government funded service.","Confirm identity, work history, references, and any registration.","Arrange a New Zealand Police vet.","Interview the worker and assess child safety risk."], visa: "A work visa is needed when the role is clearly nanny or au pair work. A Specific Purpose Work Visa fits a defined short term role, and the family or agency can support it. An Accredited Employer Work Visa may fit ongoing work and needs an accredited employer or agency. A private family's direct eligibility for that visa is Not confirmed.", age: "Not confirmed", countries: "Not confirmed", stay: "A Specific Purpose Work Visa lasts for the time needed for the defined role. An Accredited Employer Work Visa can last up to 5 years based on the job. Exact au pair stay is Not confirmed.", hours: "Not confirmed as a maximum. An Accredited Employer Work Visa job offer must have at least 30 hours a week.", source: "https://www.orangatamariki.govt.nz/working-with-children/childrens-act-requirements/safety-checking/"),
        RdRule(place: "Australia (federal)", check: "Working with Children Check or Working with Vulnerable People check, depending on the state or territory.", law: "Not confirmed", issuer: "The state or territory screening unit.", cost: "Not confirmed", validity: "Not confirmed", steps: ["Choose the state or territory where the work will happen.","Ask its screening unit if a private nanny role needs a check.","Apply through that unit and follow its identity steps."], visa: "The work options are Working Holiday visa subclass 417 and Work and Holiday visa subclass 462. No family sponsor is required for these visas. The worker applies on their own. Each visa usually limits work with one employer to 6 months.", age: "Subclass 417: ages 18 to 30 for Belgium, Estonia, Hong Kong, Japan, Malta, Netherlands, Norway, Sweden, and Taiwan. Ages 18 to 35 for Canada, Cyprus, Denmark, Finland, France, Germany, Ireland, Italy, Korea, and the United Kingdom. Subclass 462: ages 18 to 30 for all eligible passports.", countries: "Subclass 417 passports: Belgium, Canada, Republic of Cyprus, Denmark, Estonia, Finland, France, Germany, Hong Kong, Republic of Ireland, Italy, Japan, Republic of Korea, Malta, Netherlands, Norway, Sweden, Taiwan, and the United Kingdom. Taiwan official or diplomatic passports do not qualify. Subclass 462 passports: Argentina, Austria, Brazil, Chile, China, Czech Republic, Ecuador, Greece, Hungary, India, Indonesia, Israel, Luxembourg, Malaysia, Mongolia, Papua New Guinea, Peru, Poland, Portugal, San Marino, Singapore, Slovak Republic, Slovenia, Spain, Switzerland, Thailand, Türkiye, Uruguay, United States, and Vietnam. China, India, and Vietnam applicants need ballot selection.", stay: "Up to 12 months for each visa. A second or third visa may be available if the worker meets extra rules.", hours: "Not confirmed", source: "https://www.acic.gov.au/national-police-checking-service/find-out-more-information/working-children-checks"),
        RdRule(place: "England and Wales", check: "Enhanced DBS check, with a children barred list check if eligible", law: "no", issuer: "Disclosure and Barring Service", cost: "£41 DBS fee. Umbrella Body fee amount: Not confirmed", validity: "No official expiry date. The record is accurate on the issue date.", steps: ["Check if the role can have an Enhanced DBS check.","The nanny applies through a DBS Umbrella Body.","Complete the form and prove identity.","The nanny can share the certificate with the family."], visa: "The Youth Mobility Scheme visa is a listed route for au pairs. Other work visas may allow au pair work if their conditions permit it. The family does not sponsor the Youth Mobility Scheme visa.", age: "Youth Mobility Scheme: age 18 to 35 for Australia, Canada, New Zealand and South Korea. Age 18 to 30 for Andorra, Hong Kong SAR passport holders, Iceland, Japan, Monaco, San Marino, Taiwan and Uruguay. British overseas citizens, British overseas territories citizens and British nationals overseas may apply at age 18 to 30.", countries: "Youth Mobility Scheme: Andorra, Australia, Canada, Hong Kong SAR passport holders, Iceland, Japan, Monaco, New Zealand, South Korea, San Marino, Taiwan and Uruguay. Hong Kong and Taiwan require ballot selection. British overseas citizens, British overseas territories citizens and British nationals overseas may also qualify.", stay: "Youth Mobility Scheme: up to 2 years. People from Australia, Canada and New Zealand can extend for 1 more year.", hours: "No weekly hours limit is stated for the Youth Mobility Scheme.", source: "https://www.gov.uk/government/publications/dbs-guidance-leaflets/a-guide-for-parents-and-carers-employing-self-employed-workers-or-personal-employees"),
        RdRule(place: "Scotland", check: "PVG scheme membership. It is required for regulated roles. Nanny is listed. Check the role if hiring a babysitter.", law: "yes", issuer: "Disclosure Scotland", cost: "£59 to join. £18 for an existing member who continues with the same group.", validity: "Five years. Membership must be renewed to remain active.", steps: ["Check that the job is a regulated role with children.","Sign in to ScotAccount or create an account.","Apply for Confirmation of PVG scheme membership.","Share the online disclosure with the family."], visa: "The Youth Mobility Scheme visa is a listed route for au pairs. Other work visas may allow au pair work if their conditions permit it. The family does not sponsor the Youth Mobility Scheme visa.", age: "Youth Mobility Scheme: age 18 to 35 for Australia, Canada, New Zealand and South Korea. Age 18 to 30 for Andorra, Hong Kong SAR passport holders, Iceland, Japan, Monaco, San Marino, Taiwan and Uruguay. British overseas citizens, British overseas territories citizens and British nationals overseas may apply at age 18 to 30.", countries: "Youth Mobility Scheme: Andorra, Australia, Canada, Hong Kong SAR passport holders, Iceland, Japan, Monaco, New Zealand, South Korea, San Marino, Taiwan and Uruguay. Hong Kong and Taiwan require ballot selection. British overseas citizens, British overseas territories citizens and British nationals overseas may also qualify.", stay: "Youth Mobility Scheme: up to 2 years. People from Australia, Canada and New Zealand can extend for 1 more year.", hours: "No weekly hours limit is stated for the Youth Mobility Scheme.", source: "https://www.mygov.scot/pvg-scheme"),
        RdRule(place: "Northern Ireland", check: "Enhanced AccessNI disclosure for regulated child care, with a children barred list check if eligible", law: "no", issuer: "AccessNI", cost: "£32 AccessNI fee. Umbrella Body fee amount: Not confirmed", validity: "Valid for recruitment for one job. The information is accurate on the issue date.", steps: ["Check if the role is regulated activity with children.","Contact an AccessNI Umbrella Body.","Use its link and PIN to complete the application.","View or share the digital certificate in the nidirect account."], visa: "The Youth Mobility Scheme visa is a listed route for au pairs. Other work visas may allow au pair work if their conditions permit it. The family does not sponsor the Youth Mobility Scheme visa.", age: "Youth Mobility Scheme: age 18 to 35 for Australia, Canada, New Zealand and South Korea. Age 18 to 30 for Andorra, Hong Kong SAR passport holders, Iceland, Japan, Monaco, San Marino, Taiwan and Uruguay. British overseas citizens, British overseas territories citizens and British nationals overseas may apply at age 18 to 30.", countries: "Youth Mobility Scheme: Andorra, Australia, Canada, Hong Kong SAR passport holders, Iceland, Japan, Monaco, New Zealand, South Korea, San Marino, Taiwan and Uruguay. Hong Kong and Taiwan require ballot selection. British overseas citizens, British overseas territories citizens and British nationals overseas may also qualify.", stay: "Youth Mobility Scheme: up to 2 years. People from Australia, Canada and New Zealand can extend for 1 more year.", hours: "No weekly hours limit is stated for the Youth Mobility Scheme.", source: "https://www.nidirect.gov.uk/articles/checks-self-employed-or-personal-employees"),
        RdRule(place: "United States", check: "Criminal background check. No single federal check or card applies to private family home hires. State and territory rules vary.", law: "No", issuer: "Not confirmed", cost: "Not confirmed", validity: "Not confirmed", steps: ["Check your state or territory child care rules for the care setting.","If a check is required, follow the state or territory agency steps.","For an au pair, apply through a Department of State designated sponsor."], visa: "J-1 Exchange Visitor visa in the Au Pair category. A designated sponsor is required. The host family joins the sponsor program and is screened, but does not issue the visa.", age: "18 to 26 years.", countries: "No fixed country list confirmed. The Department of State says sponsors are not limited to the countries listed as prior sending countries. Confirm with a sponsor.", stay: "12 months. Extensions of 6, 9, or 12 months may be approved.", hours: "Up to 45 hours per week and 10 hours per day. EduCare has a 30 hour weekly limit.", source: "https://childcare.gov/consumer-education/what-are-my-child-care-options/informal-home-child-care"),
        RdRule(place: "Canada", check: "Vulnerable Sector Check. It applies only when the role meets the legal trust or authority test. Province and territory rules vary.", law: "No", issuer: "Local police force or other authorized body.", cost: "Not confirmed", validity: "Not confirmed", steps: ["Have the employer confirm the role involves trust or authority over children.","The employer requests the check from police or another authorized body.","The applicant gives written consent and follows local police steps."], visa: "No au pair specific visa confirmed. IEC Working Holiday gives an open work permit to eligible youth. A family does not sponsor that permit.", age: "IEC age is 18 to 35, or 18 to 30 in some partner countries. No au pair specific age confirmed.", countries: "IEC partner countries and territories are Andorra, Australia, Austria, Belgium, Chile, Costa Rica, Croatia, Czech Republic, Denmark, Estonia, Finland, France, Germany, Greece, Hong Kong, Iceland, Ireland, Italy, Japan, Latvia, Lithuania, Luxembourg, Netherlands, New Zealand, Norway, Poland, Portugal, Republic of Korea, San Marino, Slovakia, Slovenia, Spain, Sweden, Switzerland, Taiwan, and the United Kingdom. This is not an au pair specific list.", stay: "IEC can allow a stay of up to 2 years, depending on country and eligibility. No au pair specific stay confirmed.", hours: "Not confirmed", source: "https://laws.justice.gc.ca/eng/acts/C-47/page-2.html"),
        RdRule(place: "Ireland", check: "Garda Vetting disclosure, used for covered organization roles. Direct private family arrangements are excluded.", law: "No", issuer: "National Vetting Bureau of An Garda Síochána", cost: "Not confirmed", validity: "Not confirmed", steps: ["Not confirmed"], visa: "Official guidance does not confirm a separate au pair visa. Other work permission and an entry visa may be needed for a non EEA worker. Family sponsorship: Not confirmed.", age: "Not confirmed", countries: "Not confirmed", stay: "Not confirmed", hours: "Up to 48 hours a week on average under general employment law. No au pair specific limit confirmed.", source: "https://www.irishstatutebook.ie/eli/2012/act/47/enacted/en/print.html"),
        RdRule(place: "Germany", check: "Enhanced certificate of conduct, also called an extended certificate of conduct.", law: "No", issuer: "Federal Office of Justice", cost: "13 EUR", validity: "No fixed validity. The recipient decides how recent it must be. Three months is a common guide.", steps: ["Ask the family for a written request for the enhanced certificate.","Apply online through the Federal Office of Justice or at the local residents office.","Show identity details and pay 13 EUR."], visa: "Au pair visa or residence permit allowing au pair work. Federal Employment Agency approval is needed for third country applicants. The family must host and sign a contract. Formal sponsor status: Not confirmed.", age: "At least 18 when starting and under 27 when applying for the residence permit.", countries: "EU, EEA and Swiss nationals need no work permit. Third country nationals need an au pair residence title and a qualifying German speaking host family.", stay: "Six months to one year.", hours: "Up to 30 hours a week and six hours a day.", source: "https://www.bundesjustizamt.de/EN/Topics/FederalCentralCriminalRegister/CertificateofConduct/FAQ/FAQ_node.html"),
        RdRule(place: "France", check: "Criminal record extract, bulletin no. 3. No nanny specific check is confirmed.", law: "Not confirmed", issuer: "National Criminal Records Office, Ministry of Justice", cost: "Free", validity: "No period set by law. The employer may ask for a recent extract.", steps: ["The nanny applies through the Ministry of Justice website or by mail.","She enters her identity and address and confirms the request by email.","She receives the extract by email or post."], visa: "Long stay visa serving as a residence permit for Young au pair. The host family must host and sign the placement agreement. Formal sponsor status: Not confirmed.", age: "18 to 30 years.", countries: "Foreign nationals aged 18 to 30. The host family must have a different nationality. No country list is given.", stay: "One year, extendable to a maximum total of two years.", hours: "Up to 25 hours a week.", source: "https://france-visas.gouv.fr/en/jeune-au-pair"),
    ]
}
